bad = 0
for e in M:
    s = open(os.path.join(root, e["file"])).read()
    n = s.count(e["find"])
    if n != 1:
        print(f"{e['name']}: find occurs {n} times in {e['file']}", file=sys.stderr)
        bad += 1
names = [e["name"] for e in M]
assert len(names) == len(set(names)), "duplicate names"
if bad:
    sys.exit(1)
with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "mutations-config.json"), "w") as f:
    json.dump(M, f, indent=1)
    f.write("\n")
print(len(M), "mutations")
